import{_ as n,o as e,c as a,a4 as i}from"./chunks/framework.B-wJupoK.js";const t="/assets/image-20260617095008588.BG24DjLP.webp",o="/assets/image-20260617095037191.BaBg-C-Z.webp",p="/assets/ai-coding-paradigm.CLqMJhpF.svg",l="/assets/image-20260616231722135.CAwU9fGe.webp",r="/assets/image-20260616232459714.WWqBhvQ6.webp",c="/assets/deveco-architecture.BsqeOYdd.svg",d="/assets/image-20260616233209056.BCDntexA.webp",h="/assets/image-20260616233436566.Clrggx2x.webp",g="/assets/image-20260616234555763.Coex6Nch.webp",k="/assets/image-20260617000048773.2apGmxCK.webp",b="/assets/image-20260617000344447.D_EcwIjO.webp",m="/assets/image-20260617000420704.dVvP3e09.webp",u="/assets/image-20260617003416446.DRgbIKCz.webp",C="/assets/readme-screenshot.C_fug4Q8.webp",v="/assets/image-20260617004211706.DA_JXihk.webp",E="/assets/image-20260617004302892.pTxd5Kqg.webp",y="/assets/image-20260617004554642.CQaxXb6O.webp",F="/assets/image-20260617004707462.BrkF2HNA.webp",A="/assets/image-20260617004747848.DmSRHy_C.webp",I="/assets/permission-modes.BfDxkomn.svg",x=JSON.parse('{"title":"鸿蒙 DevEco CLI 与 DevEco Code 全攻略","description":"","frontmatter":{},"headers":[],"relativePath":"鸿蒙开发技巧/鸿蒙 DevEco CLI 与 DevEco Code 全攻略/鸿蒙 DevEco CLI 与 DevEco Code 全攻略.md","filePath":"鸿蒙开发技巧/鸿蒙 DevEco CLI 与 DevEco Code 全攻略/鸿蒙 DevEco CLI 与 DevEco Code 全攻略.md","lastUpdated":1781670862000,"__rawMarkdown":"# 鸿蒙 DevEco CLI 与 DevEco Code 全攻略\\n\\n> 万少：华为HDE、鸿蒙极客\\n>\\n> 个人主页：https://blog.zbztb.cn/\\n>\\n> 2025年参与孵化了20+鸿蒙应用、技术文章300+、鸿蒙知识库用户500+、鸿蒙免费课程2套、鸿蒙AI提效付费课程1套。\\n>\\n> 如果你也喜欢交流AI和鸿蒙技术，欢迎扣我。\\n\\n## 2026 HDC AI coding 会议一览\\n\\n![](assets/image-20260617095008588.webp)\\n\\n---\\n\\n![](assets/image-20260617095037191.webp)\\n\\n\\n\\n## 前言\\n\\n短短几年，AI Coding 的编程范式便由 **Copilot** 过渡到 **Vibe Coding** 最后又到了 **Agentic** 模式。\\n\\n**Copilot** 模式可以简单的理解为人**绝对**主导、AI 辅助，比如我们常用的豆包网页版，是人主动在上面输入内容，然后 AI 返回信息。\\n\\n**Vibe Coding** 模式全称*意图驱动的协同开发范式*，特点是人类可以使用自然语言去描述，然后 AI 具体执行，人类去检验 AI 产物，然后反馈结果，人类在过程中充当审核的角色。\\n\\n**Agentic** 模式全称是*目标驱动的智能体开发范式*，它强调人类制定顶层目标，AI 自主制定计划和推进工作，并且具备复杂推理能力和长期记忆，人类在关键节点进行监督和审核。\\n\\n![AI Coding 编程范式演进](assets/ai-coding-paradigm.svg)\\n\\n## 鸿蒙 AI 辅助工具的目标\\n\\n开发者在长期的鸿蒙应用开发过程中面临的问题主要有：\\n\\n1. **语法错误**：因为 ArkTS 是 TypeScript 语法的超集，所以在鸿蒙语料不足的情况下，极容易生成 TypeScript 风格的语法，导致大段程序语法错误，需要人工进行干预，AI 提效的感觉不明显。\\n2. **UI 问题**：UI 界面效果错乱、功能逻辑错误，需要人工进行审核。\\n3. **测试问题**：测试问题的整改无法做到自动化，还需要人工大力投入。\\n\\n## 常见的鸿蒙 AI Coding 场景\\n\\n![](assets/image-20260616231722135.webp)\\n\\n### 场景一\\n\\n开发者使用习惯的 AI IDE，如 **Trae**、**QOder** 或者 **WorkBuddy** 等，然后希望可以有官方出品的*知识库*、*Skill*、*MCP* 或者 *Agent* 等能力。\\n\\n然后开发者可以基于鸿蒙提供的官方命令行工具实现工程的**创建、编码、测试、编译、签名打包、分发**等流程。\\n\\n### 场景二\\n\\n为了简化开发流程，开发者希望官方提供**一站式的鸿蒙 AI 开发工具**，开箱即用、不需要额外多余配置。\\n\\n## 官方解决方案\\n\\n基于上述需求，鸿蒙官方推出了两款产品，分别是 **DevEco CLI** 和 **DevEco Code**。\\n\\n**DevEco CLI** 是鸿蒙开发命令行基座，统一整合鸿蒙开发工具链、鸿蒙专属知识库与鸿蒙精品 Skills。面向各类 AI Agent 使用的 AI 产品，将鸿蒙开发能力封装为适配 AI 调用的标准化接口，既可供给 DevEco Code 集成，也可全面开放给各类通用 AI 开发工具集成使用。\\n\\n---\\n\\n**DevEco Code** 是鸿蒙应用 AI 辅助开发工具，融合鸿蒙领域软件工程能力，深度集成 DevEco CLI 全量能力，结合鸿蒙原生应用开发特性做全链路深度优化，全方位打磨流畅高效的开发体验，倾力打造适配鸿蒙生态、贴合开发者需求的极致 Agentic 智能开发工具。\\n\\n除此之外，为了更加方便开发者发布和贡献专用于鸿蒙开发的 AI 功能能力市场，官方还做了个 **格物市场**，支持按标签、按分类、按组织检索各种 AI 资产，也支持按照业务场景，提供精品集，汇聚业务场景下的工程能力集，供开发者一键式批量下载。\\n\\n![](assets/image-20260616232459714.webp)\\n\\n![鸿蒙 AI 开发工具架构](assets/deveco-architecture.svg)\\n\\n## DevEco CLI 入门\\n\\nDevEco CLI 将 DevEco Studio 工具链统一封装为一个 CLI，内置 `ohpm`、`hvigor`、`hdc`、`emulator`、`hilog`，同时集成 HarmonyOS 技能安装、项目脚手架、本地 HarmonyOS 文档检索和 MCP 服务。\\n\\n### 环境要求\\n\\n1. 操作系统为 **macOS** 或 **Windows**\\n2. Node.js >= 18，推荐使用 **22 及以上版本**\\n3. DevEco Studio >= **6.1.0**\\n4. macOS：必须安装在 `~/Applications` 或 `/Applications` 目录下\\n\\n### 安装\\n\\n```bash\\nnpm install -g @deveco/deveco-cli@latest\\n```\\n\\n![](assets/image-20260616233209056.webp)\\n\\n### 更新\\n\\n```bash\\ndevecocli update\\n```\\n\\n### 创建工程\\n\\n```bash\\ndevecocli create --app-name MyApp\\n```\\n\\n![](assets/image-20260616233436566.webp)\\n\\n### 运行工程\\n\\n> **注意**：默认创建的工程没有配置真机签名、API 是 23。\\n\\n```bash\\ndevecocli run\\n```\\n\\n![](assets/image-20260616234555763.webp)\\n\\n### 常用命令\\n\\n> **使用技巧**：不需要记忆，后期直接让 AI 自行调用即可。\\n\\n```\\nHarmonyOS 应用开发命令行工具\\n\\nOptions:\\n  -V, --version          output the version number\\n  -h, --help             display help for command\\n\\nCommands:\\n  build [options]        构建 HarmonyOS 项目\\n  run [options]          构建并在连接的设备上运行项目\\n  update                 将 deveco-cli 更新至最新版本\\n  device                 管理已连接的设备\\n  emulator               管理模拟器实例\\n  skills                 管理 HarmonyOS 技能（skills）\\n  log [options]          获取设备应用日志\\n  create [options]       脚手架方式创建新的 HarmonyOS 应用项目\\n  init [options]         将 deveco-cli skill 安装到 AI 代理中，或将 deveco-mcp 服务器配置进 AI 代理\\n  serve                  托管内置的辅助协议服务器\\n  docs [options]         从本地文档目录搜索并阅读 HarmonyOS 文档\\n  help [command]         显示指定命令的帮助信息\\n```\\n\\n### AI Agent 集成\\n\\nDevEco CLI 支持通过命令行将自身技能添加到 Agent 中，比如添加到 **Claude Code** 中。\\n\\n> **目前支持的 Agent 有**：trae-cn, opencode, cursor, codebuddy, qoder, claude-code, codex\\n\\n```bash\\ndevecocli init --agent claude-code\\n```\\n\\n执行完上述命令后，检查全局的 Claude Code 的 Skill 目录：\\n\\n![](assets/image-20260617000048773.webp)\\n\\n然后你就可以直接在对应 Agent 中像使用普通的 Skill 去使用它了。\\n\\n```\\n/deveco-cli 修改首页的背景颜色为上-下 红-蓝渐变，然后重新运行\\n```\\n\\n![](assets/image-20260617000344447.webp)\\n\\n过程中也的确看到了它调用了 `deveco-cli` 这个 Skill。\\n\\n![](assets/image-20260617000420704.webp)\\n\\n### Server MCP\\n\\n在本地启动一个基于 stdio 的 **MCP**（Model Context Protocol）服务器，让支持 MCP 的 AI IDE / 编辑器（如 Cursor、OpenCode 等）能够直接调用 DevEco 的 ArkTS / C++ 语法检查能力。\\n\\n当你在编辑器里写 ArkTS 代码时，AI 可以通过这个 MCP 服务器调用 DevEco 的编译器，**实时发现语法错误、类型不匹配等问题**。\\n\\n可以配置全局的 MCP，也可以配置项目级别的 MCP（**推荐**），这样当在当前工程启动 Agent 时，才会加载这个 MCP。\\n\\n可以直接运行命令在当前工程中配置：\\n\\n```bash\\ndevecocli init --agent claude-code --mcp --project C:\\\\Users\\\\yeah1\\\\Desktop\\\\MyApp\\n```\\n\\n得到 `mcp.json` 文件，不同智能体的配置方式不同。\\n\\n```json\\n{\\n  \\"mcpServers\\": {\\n    \\"deveco-mcp\\": {\\n      \\"type\\": \\"stdio\\",\\n      \\"command\\": \\"devecocli\\",\\n      \\"args\\": [\\n        \\"serve\\",\\n        \\"mcp\\"\\n      ],\\n      \\"env\\": {\\n        \\"PROJECT_PATH\\": \\"C:\\\\\\\\Users\\\\\\\\yeah1\\\\\\\\Desktop\\\\\\\\MyApp\\"\\n      },\\n      \\"enabled\\": true\\n    }\\n  }\\n}\\n```\\n\\n然后 MCP 服务器会返回编译错误、警告等信息。\\n\\n![](assets/image-20260617003416446.webp)\\n\\n## DevEco Code 入门\\n\\nDevEco Code 是一款面向 HarmonyOS 开发场景的 AI Agent 工具，支持**代码编写、编译构建、设备运行、文档查阅、运行时调试及 ArkTS 问题修复**等能力。\\n\\nDevEco Code 基于开源项目 **OpenCode** 扩展开发，保留了 OpenCode 的终端交互、配置体系、Provider / MCP / Skill / Plugin 等能力，并针对 HarmonyOS 工程增加了 DevEco Studio、Hvigor、HDC、Skill、HarmonyOS 知识库、ArkTS 检查和设备调试相关集成。\\n\\n> 理解为类似 Claude Code 的 Agent，同时它更好地集成了 DevEco CLI，而且也内置了常用的 HarmonyOS 开发工具能力。\\n\\n| 工具 | 说明 |\\n| --- | --- |\\n| `build_project` | 执行编译构建并导出构建产物 |\\n| `start_app` | 在模拟器或真机上运行应用 |\\n| `hdc_log` | 收集/清理设备日志/查看连接模拟器 |\\n| `verify_ui` | 执行 UI 操作验证功能是否正确 |\\n| `check_ets_files` | ArkTS 静态语法检查 |\\n| `arkts_knowledge_search` | HarmonyOS 知识搜索 |\\n| `switch_cwd` | 切换构建项目路径 |\\n\\n![](assets/readme-screenshot.webp)\\n\\n### 安装\\n\\n```bash\\nnpm install -g @deveco/deveco-code\\n```\\n\\n### 启动\\n\\n```bash\\ndeveco\\n```\\n\\n然后它会引导你打开华为登录页面，进行登录即可。\\n\\n![](assets/image-20260617004211706.webp)\\n\\n![](assets/image-20260617004302892.webp)\\n\\n### 配置模型\\n\\n当前模型免费提供了 **GLM 5.1**，提供了每分钟 50 次请求，所以重度用户如果不够用，需要自行配置模型。\\n\\n先输入 `/modes` 进入模型切换界面，然后按下 `Ctrl+A` 进入模型配置界面。\\n\\n![](assets/image-20260617004554642.webp)\\n\\n这里选择 **DeepSeek**。\\n\\n![](assets/image-20260617004707462.webp)\\n\\n---\\n\\n![](assets/image-20260617004747848.webp)\\n\\n### UI 检查\\n\\nUI 检查就是让大模型自行检查你的页面设计是否符合要求，这里需要你的模型支持多模态，如 **Kimi 2.5**、**mimo-2.5** 等，但是当前的 DevEco Code 仅支持 Qwen 系列。\\n\\n### 权限模式\\n\\n在终端中输入 **Tab** 键进行切换。\\n\\n- **Build**：默认模式，适合工程生成、代码生成、配置修正、测试执行、推包运行和发布执行\\n\\n  > 动手干活的 Agent。你说需求，它查代码、改文件、跑构建、调试。\\n\\n- **Plan**：适合需求拆解、技术方案、发布规划、测试规划和文档生成\\n\\n  > 只出方案不敲代码的 Agent。适合把大需求拆成可执行计划，再交给 Build 去实施。\\n\\n- **Goal**：适合 SDD（*Spec-Driven Development*，**规格驱动开发**）五阶段从需求到实现与构建验证的端到端特性交付\\n\\n  > 五个阶段：**需求分析 → 架构与设计规划 → 任务拆解 → 实现 → 验证与确认**\\n\\n  > 项目经理型 Agent。适合复杂特性交付：先分析需求 → 写 spec → 拆任务 → 派子 Agent 实现 → 验证，多轮推进直到目标可验证完成。\\n\\n**如何选择？**\\n\\n- 日常编码、修 bug、跑构建 → 用 **Build**\\n- 需要先出方案、拆解需求 → 用 **Plan**\\n- 复杂端到端特性，需要完整交付流程 → 用 **Goal**\\n\\n![DevEco Code 三种权限模式对比](assets/permission-modes.svg)\\n\\n## 基本案例使用演示\\n\\n### 1. 创建工程\\n\\n### 2. 配置签名\\n\\n### 3. 开发工程\\n\\n### 4. 验收\\n\\n## 参考地址\\n\\n1. 万少博客：https://blog.zbztb.cn/\\n\\n2. DevEco CLI 源码：https://gitcode.com/openharmony-sig/deveco-cli\\n\\n3. DevEco Code 源码：https://gitcode.com/openharmony-sig/deveco-code\\n\\n4. HarmonyOS AI 辅助开发官方指南：https://developer.huawei.com/consumer/cn/doc/guidebook/aitech2026-1-0000002594922404\\n"}'),_={name:"鸿蒙开发技巧/鸿蒙 DevEco CLI 与 DevEco Code 全攻略/鸿蒙 DevEco CLI 与 DevEco Code 全攻略.md"};function q(D,s,S,B,P,w){return e(),a("div",null,[...s[0]||(s[0]=[i("",106)])])}const O=n(_,[["render",q]]);export{x as __pageData,O as default};
